CREATE INDEX idx_attachments_report ON attachments(report_id);
CREATE INDEX idx_attachments_sha ON attachments(sha256);
CREATE INDEX idx_claims_policy ON mediclaim_claims(policy_id);
CREATE INDEX idx_health_cards_member ON health_cards(member_id);
CREATE INDEX idx_hospitals_policy ON network_hospitals(policy_id);
CREATE INDEX idx_media_owner ON media(owner_id);
CREATE INDEX idx_medicines_member ON medicines(member_id);
CREATE INDEX idx_policies_member ON mediclaim_policies(member_id);
CREATE INDEX idx_reports_member_date ON reports(member_id, report_date);
CREATE INDEX idx_results_report ON lab_results(report_id);
CREATE INDEX idx_treatments_member ON treatments(member_id);
CREATE INDEX idx_vaccinations_member ON vaccinations(member_id);
CREATE INDEX idx_vitals_member_type_time ON vitals(member_id, type, measured_at);
CREATE TABLE attachments ( id TEXT PRIMARY KEY NOT NULL, report_id TEXT NOT NULL REFERENCES reports(id) ON DELETE CASCADE, kind TEXT NOT NULL, display_name TEXT NOT NULL, sha256 TEXT NOT NULL, size_bytes INTEGER NOT NULL, page_count INTEGER NOT NULL);
CREATE TABLE daily_activity ( member_id TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE, date TEXT NOT NULL, steps INTEGER, resting_hr REAL, avg_hr REAL, sleep_minutes INTEGER, weight_kg REAL, PRIMARY KEY(member_id, date));
CREATE TABLE dose_logs ( id TEXT PRIMARY KEY NOT NULL, medicine_id TEXT NOT NULL REFERENCES medicines(id) ON DELETE CASCADE, scheduled_at INTEGER NOT NULL, status TEXT NOT NULL, recorded_at INTEGER NOT NULL, UNIQUE(medicine_id, scheduled_at));
CREATE TABLE family_history ( id TEXT PRIMARY KEY NOT NULL, relation TEXT NOT NULL, condition TEXT NOT NULL, onset_age INTEGER, notes TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE health_cards ( id TEXT PRIMARY KEY NOT NULL, member_id TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE, kind TEXT NOT NULL, title TEXT NOT NULL, number TEXT NOT NULL, holder_name TEXT NOT NULL, issuer TEXT NOT NULL, valid_until TEXT, notes TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE lab_results ( id TEXT PRIMARY KEY NOT NULL, member_id TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE, report_id TEXT REFERENCES reports(id) ON DELETE SET NULL, analyte_id TEXT NOT NULL, date TEXT NOT NULL, value REAL NOT NULL, unit TEXT NOT NULL, comparator TEXT NOT NULL, ref_low REAL, ref_high REAL, printed_name TEXT NOT NULL, printed_value TEXT NOT NULL, printed_unit TEXT NOT NULL, printed_range TEXT NOT NULL, UNIQUE(member_id, analyte_id, date));
CREATE TABLE media ( id TEXT PRIMARY KEY NOT NULL, member_id TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE, owner_id TEXT NOT NULL, kind TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE medicines ( id TEXT PRIMARY KEY NOT NULL, member_id TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE, name TEXT NOT NULL, strength TEXT NOT NULL, form TEXT NOT NULL, frequency TEXT NOT NULL, dose TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT, reminder_times TEXT NOT NULL, reminders_enabled INTEGER NOT NULL, instructions TEXT NOT NULL, prescribed_by TEXT NOT NULL, report_id TEXT REFERENCES reports(id) ON DELETE SET NULL, stopped INTEGER NOT NULL);
CREATE TABLE mediclaim_claims ( id TEXT PRIMARY KEY NOT NULL, policy_id TEXT NOT NULL REFERENCES mediclaim_policies(id) ON DELETE CASCADE, member_id TEXT NOT NULL, hospital TEXT NOT NULL, admitted_on TEXT, discharged_on TEXT, kind TEXT NOT NULL, claimed REAL NOT NULL, approved REAL, status TEXT NOT NULL, claim_number TEXT NOT NULL, notes TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE mediclaim_policies ( id TEXT PRIMARY KEY NOT NULL, member_id TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE, insurer TEXT NOT NULL, plan_name TEXT NOT NULL, policy_number TEXT NOT NULL, type TEXT NOT NULL, sum_insured REAL NOT NULL, bonus REAL NOT NULL, premium REAL, start_date TEXT, end_date TEXT, covered TEXT NOT NULL, tpa_name TEXT NOT NULL, tpa_phone TEXT NOT NULL, helpline TEXT NOT NULL, agent_name TEXT NOT NULL, agent_phone TEXT NOT NULL, features TEXT NOT NULL, notes TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE members ( id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL, relationship TEXT NOT NULL, dob TEXT, sex TEXT NOT NULL, height_cm REAL, blood_group TEXT NOT NULL, allergies TEXT NOT NULL, conditions TEXT NOT NULL, ec_name TEXT NOT NULL, ec_phone TEXT NOT NULL, ec_relation TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE meta (key TEXT PRIMARY KEY NOT NULL, value TEXT NOT NULL);
CREATE TABLE network_hospitals ( id TEXT PRIMARY KEY NOT NULL, policy_id TEXT NOT NULL REFERENCES mediclaim_policies(id) ON DELETE CASCADE, name TEXT NOT NULL, address TEXT NOT NULL, city TEXT NOT NULL, pincode TEXT NOT NULL, phone TEXT NOT NULL);
CREATE TABLE reports ( id TEXT PRIMARY KEY NOT NULL, member_id TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE, type TEXT NOT NULL, title TEXT NOT NULL, report_date TEXT NOT NULL, lab_name TEXT, doctor_name TEXT, notes TEXT, created_at INTEGER NOT NULL);
CREATE TABLE treatments ( id TEXT PRIMARY KEY NOT NULL, member_id TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE, name TEXT NOT NULL, kind TEXT NOT NULL, date TEXT NOT NULL, provider TEXT NOT NULL, follow_up_date TEXT, notes TEXT NOT NULL, follow_up_done INTEGER NOT NULL);
CREATE TABLE vaccinations ( id TEXT PRIMARY KEY NOT NULL, member_id TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE, name TEXT NOT NULL, dose TEXT NOT NULL, given_date TEXT, due_date TEXT, provider TEXT NOT NULL, notes TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE visit_questions ( id TEXT PRIMARY KEY NOT NULL, member_id TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE, text TEXT NOT NULL, done INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE vitals ( id TEXT PRIMARY KEY NOT NULL, member_id TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE, type TEXT NOT NULL, value REAL NOT NULL, value2 REAL, unit TEXT NOT NULL, measured_at INTEGER NOT NULL, source TEXT NOT NULL, report_id TEXT REFERENCES reports(id) ON DELETE SET NULL, custom_name TEXT, note TEXT);
